// src/pages/SDM.jsx
import React, { useState, useEffect, useRef } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import Card from "../components/common/Card";
import Button from "../components/common/Button";
import { useUI } from "../context/UIContext";
import { topicDescriptions } from "../constants/sdm";
import styles from "../SDM.module.css"; // 引入 CSS 樣式
import Paper from "../components/common/Paper";

// 引入小幫手影片
import eveVideo from "../assets/eve_sdm_talk.mp4";

const SDM = () => {
  const navigate = useNavigate();
  const { setHeroData, setAllAnswers } = useUI();
  const [searchParams, setSearchParams] = useSearchParams();
  const videoRef = useRef(null);

  const [isPlaying, setIsPlaying] = useState(false);

  const step = searchParams.get("step") || "SELECT";
  const selectedKey = searchParams.get("topic") || null;
  const currentTopic = topicDescriptions[selectedKey];

  // 1. Hero 資訊同步 + 步驟切換時觸發對應台詞語音
  useEffect(() => {
    const heroContent = {
      SELECT: {
        title: "請選擇您想了解的主題",
        description:
          "點選下方以查看詳細的手術決策資訊，可點擊影片重複聆聽導覽。",
        speech: "請選擇您想了解的主題。點選下方以查看詳細的手術決策資訊。",
      },
      INTRO: {
        title: currentTopic?.label,
        description: "請詳閱以下說明，這將幫助您做出最適合的決定。",
        // 如果進入介紹頁，台詞直接抓取後台的長文內容 (currentTopic.content)
        speech: currentTopic?.content || "",
      },
    };

    const currentHero = heroContent[step] || heroContent.SELECT;

    setHeroData({
      imageUrl: "", // 清空，由我們自己控制影片
      title: currentHero.title,
      description: currentHero.description,
    });

    // 觸發語音與影片同步
    handlePlaySpeech(currentHero.speech);

    // 切換步驟時，確保畫面滾回頂部，讓使用者第一眼看到小幫手的臉
    window.scrollTo(0, 0);

    return () => {
      if (window.speechSynthesis) window.speechSynthesis.cancel();
    };
  }, [step, currentTopic, setHeroData]);

  // 🔊 語音與影片同步的核心處理函式
  const handlePlaySpeech = (rawText) => {
    if (!window.speechSynthesis || !videoRef.current || !rawText) return;

    window.speechSynthesis.cancel();

    // 清洗台詞：精準過濾掉 content 裡面的 <p>、<strong>、<br /> 等所有 HTML 標籤
    const pureSpeechText = rawText.replace(/<[^>]*>/g, "").trim();

    const utterance = new SpeechSynthesisUtterance(pureSpeechText);
    utterance.lang = "zh-TW";
    utterance.rate = step === "INTRO" ? 0.95 : 1.0; // 長文介紹時語音稍微放慢，聽起來更清晰、溫柔

    utterance.onstart = () => {
      setIsPlaying(true);
      if (videoRef.current) {
        videoRef.current.muted = true; // 靜音影片本身
        videoRef.current
          .play()
          .catch((err) => console.log("影片播放受阻：", err));
      }
    };

    utterance.onend = () => {
      setIsPlaying(false);
      if (videoRef.current) {
        videoRef.current.pause();
        videoRef.current.currentTime = 0; // 停止並回到閉嘴狀態
      }
    };

    utterance.onerror = () => {
      setIsPlaying(false);
      if (videoRef.current) videoRef.current.pause();
    };

    window.speechSynthesis.speak(utterance);
  };

  // 允許使用者手動點擊影片區域重複聆聽當前導覽
  const handleReplayVideo = () => {
    if (step === "INTRO" && currentTopic) {
      handlePlaySpeech(currentTopic.content);
    } else {
      handlePlaySpeech(
        "請選擇您想了解的主題。點選下方以查看詳細的手術決策資訊。",
      );
    }
  };

  // 事件處理
  const handleSelectCard = (key) =>
    setSearchParams({ step: "SELECT", topic: key });

  const handleConfirmTopic = () => {
    if (!selectedKey) return alert("請先選擇一個方案");
    setAllAnswers((prev) => ({ ...prev, selectedTopic: currentTopic.label }));
    setSearchParams({ step: "INTRO", topic: selectedKey });
  };

  const handleStartQuiz = () => {
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    navigate(`/questionnaire/${selectedKey}`);
  };

  const handleBackToSelect = () =>
    setSearchParams({ step: "SELECT", topic: selectedKey });

  return (
    <div className={styles.pageContainer}>
      {/* 整合大卡片：上半部固定為小幫手影片，下半部為動態選單或介紹 */}
      <div className={styles.interactiveCard}>
        {/* 上半部：小幫手大畫面不遮擋區 */}
        <div className={styles.videoSection} onClick={handleReplayVideo}>
          <video
            ref={videoRef}
            src={eveVideo}
            playsInline
            webkit-playsinline="true"
            preload="auto"
            loop
            className={styles.theatreVideo}
          />
          {isPlaying && (
            <div className={styles.audioBadge}>
              <span className={styles.audioDot}></span> 小幫手正在說明中...
            </div>
          )}
        </div>

        {/* 下半部：動態內容區 */}
        <div className={styles.contentSection}>
          {/* 階段一：選擇主題 */}
          {step === "SELECT" && (
            <div className={styles.fadeIn}>
              <div className={styles.cardList}>
                {Object.entries(topicDescriptions).map(([key, item]) => (
                  <Card
                    key={key}
                    title={item.label}
                    description={item.description}
                    isActive={selectedKey === key}
                    onClick={() => handleSelectCard(key)}
                  />
                ))}
              </div>

              <div className={styles.buttonGroup}>
                <Button
                  onClick={() => navigate("/selection")}
                  variant="outline"
                  fullWidth
                >
                  返回重新選擇方案
                </Button>
                <Button onClick={handleConfirmTopic} fullWidth>
                  {selectedKey ? "確認選擇並查看詳情 ➔" : "請選擇一個主題"}
                </Button>
              </div>
            </div>
          )}

          {/* 階段二：顯示長文介紹 */}
          {step === "INTRO" && currentTopic && (
            <div className={styles.fadeIn}>
              <Paper>
                <div
                  className={styles.introContentText}
                  dangerouslySetInnerHTML={{ __html: currentTopic.content }}
                />
              </Paper>
              <div className={styles.buttonGroupRow}>
                <Button
                  onClick={handleBackToSelect}
                  variant="outline"
                  style={{ flex: 1 }}
                >
                  回上一步
                </Button>
                <Button onClick={handleStartQuiz} style={{ flex: 1 }}>
                  開始了解
                </Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SDM;
